import {artifactView} from './artifact-view.js';
const api=window.argosSurface,status=document.querySelector('#surface-status'),select=document.querySelector('#display'),host=document.querySelector('#surface-artifact');let state;
function update(next){state=next;document.querySelector('#surface-context').textContent=next.ref?`${next.ref.project} · ${next.ref.task_id} · ${next.ref.path}`:'Superficie disponible. Selecciona un artefacto en Proyectos o pídeselo a ARGOS.';select.replaceChildren(...next.displays.map(d=>{const o=document.createElement('option');o.value=d.key;o.textContent=`${d.ordinal} · ${d.label}`;return o}));select.value=next.display;status.textContent=next.error;document.querySelector('#return').disabled=!next.ref}
async function action(operation){try{status.textContent='Actualizando…';await api.action({operation,...(operation==='move'?{display:select.value}:{})});status.textContent=''}catch(e){status.textContent=e.message}}
for(const operation of ['move','return','close','fullscreen'])document.getElementById(operation).onclick=()=>action(operation);
api.onChange(update);update(await api.state());if(state.ref){try{const value=await api.artifact();const view=artifactView(value,{refresh:()=>api.artifact()});host.append(view);window.addEventListener('pagehide',()=>view.dispose())}catch(e){status.textContent='No se pudo recuperar el artefacto: '+e.message}}
